        // Fill entries in other rows 
        for (i = 1; i < M; i++) 
        {
            // Copy values from row at index lps 
            for (x = 0; x < NO_OF_CHARS; x++) 
            {
                TF[i][x] = TF[lps][x];
            }

            // Update the entry corresponding to this character 
            TF[i][pat[i]] = i + 1;

            // Update lps for next row to be filled 
            if (i < M) 
